// Generated by dataflare client-init. No admin credentials belong in this file.
const HOST = "https://observe.gmac.io";
const PROJECT = "educateos-site";

export interface DataflareEnv {
  DATAFLARE?: { fetch(request: Request): Promise<Response> };
}

export interface CaptureEvent {
  event: string;
  /** Required stable identity: a pseudonymous person/device id or a case id. */
  distinct_id: string;
  user_id?: string;
  session_id?: string;
  props?: Record<string, unknown>;
  /** Persist both id and ts with an outbox record to retry the same event. */
  id?: string;
  ts?: number;
}

/** Mount before your router. Only public capture paths are forwarded. */
export async function dataflareProxy(request: Request, env: DataflareEnv): Promise<Response | null> {
  const url = new URL(request.url);
  if (url.pathname !== '/_glass' && !url.pathname.startsWith('/_glass/')) return null;
  const path = url.pathname.slice('/_glass'.length);
  const method = ['/s.js', '/replay.js'].includes(path) ? 'GET'
    : ['/e', '/f', '/r'].includes(path) ? 'POST' : null;
  if (!method) return new Response('Not found', { status: 404 });
  if (request.method !== method) return new Response('Method not allowed', {
    status: 405, headers: { Allow: method },
  });
  // Preserve Cloudflare request metadata and visitor headers through the binding.
  // Never forward app credentials or cookies to the analytics service.
  if (!env.DATAFLARE) return new Response('Configure the DATAFLARE service binding for same-origin capture.', { status: 503 });
  const target = new URL(HOST + path + url.search);
  const forwarded = new Request(target, request);
  forwarded.headers.delete('Authorization');
  forwarded.headers.delete('Cookie');
  return env.DATAFLARE.fetch(forwarded);
}

/** Use from a Worker or a Durable Object. A binding is preferred; otherwise HTTPS ingest is used. */
export async function capture(env: DataflareEnv, event: CaptureEvent): Promise<void> {
  if (!event.distinct_id || !event.event || event.event.length > 200 || event.event.startsWith('$') || Array.from(event.event).some((character) => character.charCodeAt(0) < 32)) {
    throw new Error('Pass a distinct_id and a custom event name.');
  }
  if ((event.id !== undefined && (!event.id || event.id.length > 64)) ||
      (event.ts !== undefined && !Number.isFinite(event.ts))) {
    throw new Error('Pass an event id of 1–64 characters and a finite timestamp.');
  }
  const send = env.DATAFLARE ? (request: Request) => env.DATAFLARE!.fetch(request) : fetch;
  const response = await send(new Request(HOST + '/e', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({
      project: PROJECT,
      lib: 'worker/client-init',
      // No sent_at: replaying an outbox must retain the original timestamp.
      events: [{ ...event, id: event.id ?? crypto.randomUUID(), ts: event.ts ?? Date.now() }],
    }),
  }));
  if (!response.ok) throw new Error('Dataflare capture failed: HTTP ' + response.status);
  if (response.status === 204) throw new Error('Dataflare did not acknowledge capture. Upgrade the analytics Worker before using required delivery.');
  const result = await response.json() as { accepted?: number; dropped?: number };
  if (result.accepted !== 1 || result.dropped !== 0) throw new Error('Dataflare rejected the event. Check the project collection policy and event catalog.');
}
